-- Velours v4 : 10 profils de démo (fictifs, photos générées par IA) + « Bof » qu'on peut annuler
-- À coller une seule fois dans Supabase → SQL Editor → Run.

-- 1) Pouvoir annuler son propre « Bof »
drop policy if exists "l_delete_pass" on public.likes;
create policy "l_delete_pass" on public.likes for delete to authenticated using (liker = auth.uid() and kind = 'pass');

-- 2) Clara redevient visible pour Loïc (on efface ses « Bof » sur Clara)
delete from public.likes l using public.profiles a, public.profiles b
where l.liker = a.id and l.likee = b.id and l.kind = 'pass'
  and (a.name ilike 'lo_c%' or a.name ilike 'loic%') and b.name ilike 'clara%';

-- 3) 10 comptes de démo (on ne peut pas s'y connecter : pas de mot de passe)
on conflict (id) do nothing;

on conflict (id) do update set name=excluded.name, bio=excluded.bio, city=excluded.city, photos=excluded.photos, interests=excluded.interests;

-- Position : autour de la tienne (ou de Lyon), pour que le filtre de distance les montre
select v.id::uuid, round((coalesce(m.lat, 45.76) + v.dlat)::numeric, 2), round((coalesce(m.lng, 4.84) + v.dlng)::numeric, 2)
from (values ('5eed0000-0000-4000-8000-000000000001',0.01,0.012), ('5eed0000-0000-4000-8000-000000000002',0.018,0.005), ('5eed0000-0000-4000-8000-000000000003',0.03,0.04), ('5eed0000-0000-4000-8000-000000000004',-0.004,-0.008), ('5eed0000-0000-4000-8000-000000000005',0.012,-0.006), ('5eed0000-0000-4000-8000-000000000006',-0.02,0.003), ('5eed0000-0000-4000-8000-000000000007',-0.006,0.022), ('5eed0000-0000-4000-8000-000000000008',0.022,-0.012), ('5eed0000-0000-4000-8000-000000000009',0.04,-0.06), ('5eed0000-0000-4000-8000-000000000010',-0.025,0.03)) as v(id, dlat, dlng)
left join lateral (select lat, lng from public.locations where user_id::text not like '5eed%' order by updated_at desc limit 1) m on true
on conflict (user_id) do update set lat = excluded.lat, lng = excluded.lng;

-- 4) Autoriser l'envoi des 30 photos de démo, seulement ces fichiers-là et seulement jusqu'au 27 novembre
drop policy if exists "seed_photos" on storage.objects;
create policy "seed_photos" on storage.objects for insert to anon, authenticated
  with check (bucket_id = 'photos' and now() < '2026-11-27' and name in ('seed/lea-1.jpg', 'seed/lea-2.jpg', 'seed/lea-3.jpg', 'seed/yasmine-1.jpg', 'seed/yasmine-2.jpg', 'seed/yasmine-3.jpg', 'seed/chloe-1.jpg', 'seed/chloe-2.jpg', 'seed/chloe-3.jpg', 'seed/amara-1.jpg', 'seed/amara-2.jpg', 'seed/amara-3.jpg', 'seed/manon-1.jpg', 'seed/manon-2.jpg', 'seed/manon-3.jpg', 'seed/sofia-1.jpg', 'seed/sofia-2.jpg', 'seed/sofia-3.jpg', 'seed/lina-1.jpg', 'seed/lina-2.jpg', 'seed/lina-3.jpg', 'seed/zoe-1.jpg', 'seed/zoe-2.jpg', 'seed/zoe-3.jpg', 'seed/anais-1.jpg', 'seed/anais-2.jpg', 'seed/anais-3.jpg', 'seed/maya-1.jpg', 'seed/maya-2.jpg', 'seed/maya-3.jpg'));

notify pgrst, 'reload schema';
