('5eed0000-0000-4000-8000-000000000001','Léa','1999-04-12','Lesbienne','Une histoire d''amour','Rooftops au coucher du soleil et robes rouges. Je cherche quelqu''un pour refaire le monde un verre à la main 🍷','Lyon 2e','Le premier date idéal…','Un rooftop, une playlist douce et on oublie l''heure.',array['🍷 Apéros','🎶 Concerts','🏖️ Voyages'],array['https://hmscauwtqvzjfdzzmsdf.supabase.co/storage/v1/object/public/photos/seed/lea-1.jpg','https://hmscauwtqvzjfdzzmsdf.supabase.co/storage/v1/object/public/photos/seed/lea-2.jpg','https://hmscauwtqvzjfdzzmsdf.supabase.co/storage/v1/object/public/photos/seed/lea-3.jpg'],true),
('5eed0000-0000-4000-8000-000000000002','Yasmine','1997-08-03','Bi','Une histoire d''amour','Avocate le jour, reine du brunch le week-end. Mon rire s''entend de loin ☕','Lyon 6e','Je craque pour…','Les regards qui durent une seconde de trop.',array['☕ Cafés','🍳 Cuisine','💃 Danse'],array['https://hmscauwtqvzjfdzzmsdf.supabase.co/storage/v1/object/public/photos/seed/yasmine-1.jpg','https://hmscauwtqvzjfdzzmsdf.supabase.co/storage/v1/object/public/photos/seed/yasmine-2.jpg','https://hmscauwtqvzjfdzzmsdf.supabase.co/storage/v1/object/public/photos/seed/yasmine-3.jpg'],true),
('5eed0000-0000-4000-8000-000000000003','Chloé','2001-06-21','Pan','Des rencontres, on verra','Festivals, glaces à toute heure et fous rires. Je te parie que je connais toutes les paroles 🎤','Villeurbanne','Ma playlist du moment…','Pop, électro et un vieux tube des années 2000.',array['🎶 Concerts','🎤 Karaoké','📸 Photo'],array['https://hmscauwtqvzjfdzzmsdf.supabase.co/storage/v1/object/public/photos/seed/chloe-1.jpg','https://hmscauwtqvzjfdzzmsdf.supabase.co/storage/v1/object/public/photos/seed/chloe-2.jpg','https://hmscauwtqvzjfdzzmsdf.supabase.co/storage/v1/object/public/photos/seed/chloe-3.jpg'],true),
('5eed0000-0000-4000-8000-000000000004','Amara','1996-02-14','Lesbienne','Une histoire d''amour','Curatrice dans une galerie d''art. J''aime les belles choses, et les gens qui osent ✨','Lyon 1er','On s''entendra bien si…','…tu aimes les expos autant que les soirées qui finissent tard.',array['🎨 Art','🍷 Apéros','🏖️ Voyages'],array['https://hmscauwtqvzjfdzzmsdf.supabase.co/storage/v1/object/public/photos/seed/amara-1.jpg','https://hmscauwtqvzjfdzzmsdf.supabase.co/storage/v1/object/public/photos/seed/amara-2.jpg','https://hmscauwtqvzjfdzzmsdf.supabase.co/storage/v1/object/public/photos/seed/amara-3.jpg'],true),
